    meta2 = {f: {"bytes": len(b2[f]), "sha256": _sha_bytes(b2[f]), "n_whole_chunks": None} for f in FAMILIES}
    comp = {f: {"0024_part": comp2[f], "new_part": compn[f], "bytes": len(blobs[f])} for f in FAMILIES}
    if pins_0024 is None and os.path.exists(MANIFEST_PATH):   # 0024's blob as the banked build hashed it, before any candidate is cut
        banked = json.load(open(MANIFEST_PATH, encoding="utf-8"))["per_family"]
        bad = {f: (meta2[f]["sha256"][:12], meta2[f]["bytes"], banked[f]["blob_0024_sha256"][:12], banked[f]["blob_0024_bytes"],
                   [a for a, v in (comp2[f].get("per_archive") or {}).items() if v != banked[f]["composition"]["0024_part"]["per_archive"].get(a)])
               for f in FAMILIES if meta2[f]["sha256"] != banked[f]["blob_0024_sha256"]}
        if bad:
            raise RuntimeError("0024's blob rebuilt here is not the one the banked realfit3 manifest hashed (per family: rebuilt sha256, bytes; banked "
                               f"sha256, bytes; archives whose member count or bytes differ): {bad}; Python {sys.version.split()[0]}")
    return blobs, comp, meta2, b2

